-- =====================================================================
-- MypeInventario - PostgreSQL - Carga de datos (500 filas por tabla, 20 tablas)
-- Generado a partir del diccionario de datos (tipos, CHECK, UNIQUE y FK).
-- Datos de ejemplo: rubros de ropa, calzado y bazar; fechas entre 15/08/2026 y 14/11/2026.
--
-- ANTES DE EJECUTAR (conexion a Oracle, usuario MYPE_INVENTARIO), comprobar los ids que se referencian
-- entre motores (este script supone 1..20 sucursales y 1..500 SKU, ventas y empleados):
--   SELECT 'SUCURSAL' t, MIN(id_sucursal) mn, MAX(id_sucursal) mx, COUNT(*) n FROM Sucursal
--   UNION ALL SELECT 'VARIANTESKU', MIN(id_sku),      MAX(id_sku),      COUNT(*) FROM VarianteSKU
--   UNION ALL SELECT 'VENTA',       MIN(id_venta),    MAX(id_venta),    COUNT(*) FROM Venta
--   UNION ALL SELECT 'EMPLEADO',    MIN(id_empleado), MAX(id_empleado), COUNT(*) FROM Empleado;
--
-- Orden respetando las FK. Tablas vacias: si ya hay datos, TRUNCATE ... RESTART IDENTITY CASCADE antes.
-- Si las tablas estan en un esquema propio, descomentar y ajustar:
-- SET search_path TO mype_inventario, public;
-- =====================================================================
SET client_encoding = 'UTF8';
BEGIN;

