-- Reiniciar las secuencias IDENTITY para que los proximos INSERT continuen en 501
ALTER TABLE TipoMovimiento ALTER COLUMN id_tipo_movimiento RESTART WITH 501;
ALTER TABLE Inventario ALTER COLUMN id_inventario RESTART WITH 501;
ALTER TABLE Almacen ALTER COLUMN id_almacen RESTART WITH 501;
ALTER TABLE UbicacionProducto ALTER COLUMN id_ubicacion RESTART WITH 501;
ALTER TABLE ConfiguracionReabastecimiento ALTER COLUMN id_configuracion RESTART WITH 501;
ALTER TABLE Stock ALTER COLUMN id_stock RESTART WITH 501;
ALTER TABLE MovimientoInventario ALTER COLUMN id_movimiento RESTART WITH 501;
ALTER TABLE HistorialStock ALTER COLUMN id_historial RESTART WITH 501;
ALTER TABLE AlertaReabastecimiento ALTER COLUMN id_alerta RESTART WITH 501;
ALTER TABLE CodigoBarras ALTER COLUMN id_codigo_barras RESTART WITH 501;
ALTER TABLE Devolucion ALTER COLUMN id_devolucion RESTART WITH 501;
ALTER TABLE DetalleDevolucion ALTER COLUMN id_detalle_devolucion RESTART WITH 501;
ALTER TABLE Promocion ALTER COLUMN id_promocion RESTART WITH 501;
ALTER TABLE ProductoPromocion ALTER COLUMN id_producto_promocion RESTART WITH 501;
ALTER TABLE TransferenciaInventario ALTER COLUMN id_transferencia RESTART WITH 501;
ALTER TABLE DetalleTransferencia ALTER COLUMN id_detalle_transferencia RESTART WITH 501;
ALTER TABLE ConteoInventario ALTER COLUMN id_conteo RESTART WITH 501;
ALTER TABLE DetalleConteoInventario ALTER COLUMN id_detalle_conteo RESTART WITH 501;
ALTER TABLE LoteProducto ALTER COLUMN id_lote RESTART WITH 501;
ALTER TABLE DetalleLote ALTER COLUMN id_detalle_lote RESTART WITH 501;

COMMIT;

